mapper.select:
SELECT t.id, t.origin, t.createdAt, t.staff, t.division, t.category, t.name, t.phone, t.source, t.content, t.memo, t.status, t.reservation, t.initialPrice, t.upsellPrice, t.prevStatus FROM ( /* ===== customers 분기 ===== */ SELECT c.customer_id AS id, 'CUSTOMER' AS origin, c.customer_created_at AS createdAt, u.user_name AS staff, c.customer_division AS division, c.customer_category AS category, c.customer_name AS name, c.customer_phone AS phone, c.customer_source AS source, c.customer_content AS content, c.customer_memo AS memo, c.customer_status AS status, c.customer_prev_status AS prevStatus, c.customer_promise_time AS promiseAt, CASE WHEN c.customer_promise_time IS NULL THEN NULL WHEN c.customer_status = '내방' THEN CONCAT_WS( '\n', DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i'), ( SELECT mr.room_name FROM visit_schedule vs JOIN meeting_rooms mr ON mr.room_id = vs.room_id WHERE vs.customer_id = c.customer_id ORDER BY vs.updated_at DESC, vs.visit_id DESC LIMIT 1 ) ) ELSE DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i') END AS reservation, c.initial_price AS initialPrice, c.upsell_price AS upsellPrice FROM customers c LEFT JOIN users u ON u.user_id = c.user_id WHERE 1=1
AND c.customer_created_at >= #{dateFrom}
AND c.customer_created_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)
AND c.customer_division = #{division}
AND c.customer_source = #{expertName}
AND c.customer_status IN ('부재1', '부재2', '부재3', '부재4', '부재5')
AND c.customer_status = #{status}
UNION ALL
/* ===== customers_duplicate 분기 ===== */ SELECT d.duplicate_id AS id, 'DUPLICATE' AS origin, d.duplicate_created_at AS createdAt, u2.user_name AS staff, '중복' AS division, d.duplicate_category AS category, d.duplicate_name AS name, c2.customer_phone AS phone, d.duplicate_source AS source, d.duplicate_content AS content, d.duplicate_memo AS memo, '없음' AS status, NULL AS prevStatus, NULL AS promiseAt, NULL AS reservation, 0 AS initialPrice, 0 AS upsellPrice FROM customers_duplicate d JOIN customers c2 ON c2.customer_id = d.customer_id LEFT JOIN users u2 ON u2.user_id = c2.user_id WHERE d.duplicate_display = 1
AND d.duplicate_created_at >= #{dateFrom}
AND d.duplicate_created_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)
) t WHERE 1=1
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM ( /* ===== customers 분기 ===== */ SELECT c.customer_id AS id, 'CUSTOMER' AS origin, c.customer_created_at AS createdAt, u.user_name AS staff, c.customer_division AS division, c.customer_category AS category, c.customer_name AS name, c.customer_phone AS phone, c.customer_source AS source, c.customer_content AS content, c.customer_memo AS memo, c.customer_status AS status, c.customer_prev_status AS prevStatus, c.customer_promise_time AS promiseAt, DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i') AS reservation FROM customers c LEFT JOIN users u ON u.user_id = c.user_id WHERE 1=1
AND c.customer_created_at >= #{dateFrom}
AND c.customer_created_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)
AND c.customer_division = #{division}
AND c.customer_source = #{expertName}
AND c.customer_status IN ('부재1', '부재2', '부재3', '부재4', '부재5')
AND c.customer_status = #{status}
UNION ALL
/* ===== customers_duplicate 분기 ===== */ SELECT d.duplicate_id AS id, 'DUPLICATE' AS origin, d.duplicate_created_at AS createdAt, u2.user_name AS staff, '중복' AS division, d.duplicate_category AS category, d.duplicate_name AS name, c2.customer_phone AS phone, d.duplicate_source AS source, d.duplicate_content AS content, d.duplicate_memo AS memo, '없음' AS status, NULL AS prevStatus, NULL AS promiseAt, CAST(NULL AS CHAR(20)) AS reservation FROM customers_duplicate d JOIN customers c2 ON c2.customer_id = d.customer_id LEFT JOIN users u2 ON u2.user_id = c2.user_id WHERE d.duplicate_display = 1
AND d.duplicate_created_at >= #{dateFrom}
AND d.duplicate_created_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)
) t WHERE 1=1

SELECT c.customer_id AS id, 'CUSTOMER' AS origin, c.customer_created_at AS createdAt, u.user_name AS staff, c.customer_division AS division, c.customer_category AS category, c.customer_name AS name, c.customer_phone AS phone, c.customer_source AS source, c.customer_content AS content, c.customer_memo AS memo, c.customer_status AS status, c.customer_prev_status AS prevStatus, CASE WHEN c.customer_promise_time IS NULL THEN NULL WHEN c.customer_status = '내방' THEN CONCAT_WS( '\n', DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i'), ( SELECT mr.room_name FROM visit_schedule vs JOIN meeting_rooms mr ON mr.room_id = vs.room_id WHERE vs.customer_id = c.customer_id ORDER BY vs.updated_at DESC, vs.visit_id DESC LIMIT 1 ) ) ELSE DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i') END AS reservation, c.initial_price AS initialPrice, c.upsell_price AS upsellPrice FROM customers c JOIN users u ON u.user_id = c.user_id
WHERE c.user_id IN (SELECT user_id FROM users WHERE center_id = #{centerId}) AND c.customer_status != '없음'
LIMIT #{size} OFFSET #{offset}

SELECT c.customer_id AS id, 'CUSTOMER' AS origin, c.customer_created_at AS createdAt, u.user_name AS staff, c.customer_division AS division, c.customer_category AS category, c.customer_name AS name, c.customer_phone AS phone, c.customer_source AS source, c.customer_content AS content, c.customer_memo AS memo, c.customer_status AS status, c.customer_prev_status AS prevStatus, CASE WHEN c.customer_promise_time IS NULL THEN NULL WHEN c.customer_status = '내방' THEN CONCAT_WS( '\n', DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i'), ( SELECT mr.room_name FROM visit_schedule vs JOIN meeting_rooms mr ON mr.room_id = vs.room_id WHERE vs.customer_id = c.customer_id ORDER BY vs.updated_at DESC, vs.visit_id DESC LIMIT 1 ) ) ELSE DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i') END AS reservation, c.initial_price AS initialPrice, c.upsell_price AS upsellPrice FROM customers c LEFT JOIN users u ON u.user_id = c.user_id
WHERE c.user_id = #{userId} AND c.customer_status != '없음'
LIMIT #{size} OFFSET #{offset}

SELECT t.id, t.origin, t.createdAt, t.staff, t.division, t.category, t.name, t.phone, t.source, t.content, t.memo, t.status, t.reservation, t.initialPrice, t.upsellPrice, t.prevStatus FROM ( /* 1. customers */ SELECT c.customer_id AS id, 'CUSTOMER' AS origin, c.customer_created_at AS createdAt, u.user_name AS staff, c.customer_division AS division, c.customer_category AS category, c.customer_name AS name, c.customer_phone AS phone, c.customer_source AS source, c.customer_content AS content, c.customer_memo AS memo, c.customer_status AS status, c.customer_prev_status AS prevStatus, c.customer_promise_time AS promiseAt, CASE WHEN c.customer_promise_time IS NULL THEN NULL WHEN c.customer_status = '내방' THEN CONCAT_WS( '\n', DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i'), ( SELECT mr.room_name FROM visit_schedule vs JOIN meeting_rooms mr ON mr.room_id = vs.room_id WHERE vs.customer_id = c.customer_id ORDER BY vs.updated_at DESC, vs.visit_id DESC LIMIT 1 ) ) ELSE DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i') END AS reservation, c.initial_price AS initialPrice, c.upsell_price AS upsellPrice FROM customers c LEFT JOIN users u ON u.user_id = c.user_id WHERE 1=1 AND c.customer_source IN ( SELECT DISTINCT e.expert_name FROM experts e JOIN users u2 ON u2.expert_id = e.expert_id WHERE u2.center_id = #{centerId} ) AND c.customer_created_at >= #{dateFrom} AND c.customer_created_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)
UNION ALL
/* 2. customers_duplicate */ SELECT d.duplicate_id AS id, 'DUPLICATE' AS origin, d.duplicate_created_at AS createdAt, u2.user_name AS staff, '중복' AS division, d.duplicate_category AS category, d.duplicate_name AS name, c2.customer_phone AS phone, d.duplicate_source AS source, d.duplicate_content AS content, d.duplicate_memo AS memo, '없음' AS status, NULL AS prevStatus, NULL AS promiseAt, NULL AS reservation, 0 AS initialPrice, 0 AS upsellPrice FROM customers_duplicate d JOIN customers c2 ON c2.customer_id = d.customer_id LEFT JOIN users u2 ON u2.user_id = c2.user_id WHERE d.duplicate_display = 1 AND d.duplicate_source IN ( SELECT DISTINCT e.expert_name FROM experts e JOIN users u3 ON u3.expert_id = e.expert_id WHERE u3.center_id = #{centerId} ) AND d.duplicate_created_at >= #{dateFrom} AND d.duplicate_created_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY) ) t WHERE 1=1
LIMIT #{size} OFFSET #{offset}

SELECT t.id, t.origin, t.createdAt, t.staff, t.division, t.category, t.name, t.phone, t.source, t.content, t.memo, t.status, t.reservation, t.initialPrice, t.upsellPrice, t.prevStatus FROM ( /* 1. customers */ SELECT c.customer_id AS id, 'CUSTOMER' AS origin, c.customer_created_at AS createdAt, u.user_name AS staff, c.customer_division AS division, c.customer_category AS category, c.customer_name AS name, c.customer_phone AS phone, c.customer_source AS source, c.customer_content AS content, c.customer_memo AS memo, c.customer_status AS status, c.customer_prev_status AS prevStatus, c.customer_promise_time AS promiseAt, CASE WHEN c.customer_promise_time IS NULL THEN NULL WHEN c.customer_status = '내방' THEN CONCAT_WS( '\n', DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i'), ( SELECT mr.room_name FROM visit_schedule vs JOIN meeting_rooms mr ON mr.room_id = vs.room_id WHERE vs.customer_id = c.customer_id ORDER BY vs.updated_at DESC, vs.visit_id DESC LIMIT 1 ) ) ELSE DATE_FORMAT(c.customer_promise_time, '%c월 %e일 %H:%i') END AS reservation, c.initial_price AS initialPrice, c.upsell_price AS upsellPrice FROM customers c LEFT JOIN users u ON u.user_id = c.user_id WHERE 1=1 AND c.customer_source = (SELECT expert_name FROM experts WHERE expert_id = #{myExpertId}) AND c.customer_created_at >= #{dateFrom} AND c.customer_created_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)
UNION ALL
/* 2. customers_duplicate */ SELECT d.duplicate_id AS id, 'DUPLICATE' AS origin, d.duplicate_created_at AS createdAt, u2.user_name AS staff, '중복' AS division, d.duplicate_category AS category, d.duplicate_name AS name, c2.customer_phone AS phone, d.duplicate_source AS source, d.duplicate_content AS content, d.duplicate_memo AS memo, '없음' AS status, NULL AS prevStatus, NULL AS promiseAt, NULL AS reservation, 0 AS initialPrice, 0 AS upsellPrice FROM customers_duplicate d JOIN customers c2 ON c2.customer_id = d.customer_id LEFT JOIN users u2 ON u2.user_id = c2.user_id WHERE d.duplicate_display = 1 AND d.duplicate_source = (SELECT expert_name FROM experts WHERE expert_id = #{myExpertId}) AND d.duplicate_created_at >= #{dateFrom} AND d.duplicate_created_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY) ) t WHERE 1=1
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM customers c
         JOIN users u ON u.user_id = c.user_id
WHERE c.customer_id = #{customerId}
  AND u.center_id = #{centerId}

SELECT COUNT(*)
FROM customers
WHERE customer_id = #{customerId}
  AND user_id = #{userId}

SELECT EXISTS (
    SELECT 1
    FROM customers c
             JOIN experts me ON me.expert_id = #{expertId}
    WHERE c.customer_id = #{customerId}
      AND TRIM(me.expert_name) = TRIM(c.customer_source)
)

